set -euo pipefail
db_user=$(docker exec postgres printenv POSTGRES_USER)
docker exec -i postgres psql -X -qAt -v ON_ERROR_STOP=1 -U "$db_user" -d coaching_db <<'SQL'
BEGIN READ ONLY;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['LGS','TYT','SAY','EA','SOZ','DIL'])scope CROSS JOIN unnest(ARRAY['student','teacher'])actor CROSS JOIN unnest(ARRAY['manual','automatic'])mode LEFT JOIN coaching.study_plan_revisions p ON p."Title"='RG26 '||scope||' '||actor||CASE WHEN mode='automatic' THEN '-v2' ELSE '' END||' '||mode WHERE p."Id" IS NULL OR p."Status"<>2 OR p."IsActive") THEN RAISE EXCEPTION 'Incomplete regression matrix'; END IF;
 IF (SELECT count(*) FROM coaching.study_plan_revisions WHERE "Title" LIKE 'RG26 % manual' OR "Title" LIKE 'RG26 %-v2 automatic')<>24 THEN RAISE EXCEPTION 'Duplicate or missing final test plan'; END IF;
 IF EXISTS(SELECT 1 FROM coaching.study_plan_revisions p WHERE p."Title" LIKE 'RG26 %-v2 automatic' AND (SELECT count(DISTINCT t."WeeklyLessonId") FROM coaching.study_plan_tasks t WHERE t."RevisionId"=p."Id")<>CASE split_part(p."Title",' ',2) WHEN 'LGS' THEN 6 WHEN 'TYT' THEN 9 WHEN 'SAY' THEN 13 WHEN 'EA' THEN 13 WHEN 'SOZ' THEN 16 WHEN 'DIL' THEN 10 END) THEN RAISE EXCEPTION 'Final automatic plan omitted a selected lesson'; END IF;
 IF EXISTS(SELECT 1 FROM coaching.study_plan_revisions p WHERE p."Title" LIKE 'RG26 %-v2 automatic' AND (SELECT sum(t."PlannedMinutes") FROM coaching.study_plan_tasks t WHERE t."RevisionId"=p."Id")<>CASE split_part(p."Title",' ',2) WHEN 'LGS' THEN 11970 WHEN 'TYT' THEN 31048 WHEN 'SAY' THEN 51393 WHEN 'EA' THEN 46058 WHEN 'SOZ' THEN 42763 WHEN 'DIL' THEN 35998 END) THEN RAISE EXCEPTION 'Final automatic minutes incomplete'; END IF;
 IF EXISTS(SELECT 1 FROM coaching.study_plan_tasks t JOIN coaching.study_plan_revisions p ON p."Id"=t."RevisionId" WHERE p."Title" LIKE 'RG26 %' AND (t."PlannedDate"<'2026-10-26' OR t."PlannedDate">'2027-06-01' OR t."PlannedStartMinute" IS NULL)) THEN RAISE EXCEPTION 'Invalid plan date/time'; END IF;
 IF EXISTS(SELECT 1 FROM (SELECT t."PlannedStartMinute" start_min,lag(t."PlannedStartMinute"+t."PlannedMinutes") OVER(PARTITION BY t."RevisionId",t."PlannedDate" ORDER BY t."PlannedStartMinute",t."Id") prev_end FROM coaching.study_plan_tasks t JOIN coaching.study_plan_revisions p ON p."Id"=t."RevisionId" WHERE p."Title" LIKE 'RG26 %')x WHERE start_min<prev_end) THEN RAISE EXCEPTION 'Overlapping test tasks'; END IF;
 IF EXISTS(SELECT 1 FROM coaching.study_plan_tasks t JOIN coaching.study_plan_revisions p ON p."Id"=t."RevisionId" WHERE p."Title" LIKE 'RG26 % automatic' AND NOT EXISTS(SELECT 1 FROM coaching.study_plan_task_outcomes l JOIN coaching.study_catalog_outcomes o ON o."Id"=l."OutcomeId" JOIN coaching.outcome_duration_estimates e ON e."Id"=l."EstimateId" WHERE l."TaskId"=t."Id")) THEN RAISE EXCEPTION 'Missing automatic outcome/estimate link'; END IF;
 IF EXISTS(SELECT 1 FROM coaching.study_plan_tasks t JOIN coaching.study_plan_revisions p ON p."Id"=t."RevisionId" JOIN coaching.study_catalog_topics top ON top."Id"=t."TopicId" JOIN coaching.study_catalog_lessons lesson ON lesson."Id"=top."LessonId" WHERE p."Title" LIKE 'RG26 LGS % automatic' AND lesson."ExamCode"<>'LGS') THEN RAISE EXCEPTION 'LGS scope mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM coaching.study_plan_tasks t JOIN coaching.study_plan_revisions p ON p."Id"=t."RevisionId" WHERE p."Title" LIKE 'RG26 % automatic' AND p."Title" NOT LIKE 'RG26 LGS %' AND NOT EXISTS(SELECT 1 FROM coaching.study_catalog_yks_scopes s WHERE s."TopicId"=t."TopicId" AND s."ScoreType"=split_part(p."Title",' ',2))) THEN RAISE EXCEPTION 'YKS score scope mismatch'; END IF;
END $$;
SELECT json_build_object('title',p."Title",'id',p."Id",'archived',p."Status"=2,'tasks',count(t.*),'minutes',sum(t."PlannedMinutes"),'lessons',count(DISTINCT t."WeeklyLessonId"),'firstDate',min(t."PlannedDate"),'lastDate',max(t."PlannedDate")) FROM coaching.study_plan_revisions p JOIN coaching.study_plan_tasks t ON t."RevisionId"=p."Id" WHERE p."Title" LIKE 'RG26 % manual' OR p."Title" LIKE 'RG26 %-v2 automatic' GROUP BY p."Id" ORDER BY p."Title";
SELECT json_build_object('matrixCases',24,'noOverlaps',true,'allDatesWithinTarget',true,'outcomeLinksIntact',true,'scoreScopesCorrect',true,'allSelectedLessonsPresent',true);
COMMIT;
SQL
docker exec postgres psql -X -qAt -v ON_ERROR_STOP=1 -U "$db_user" -d notification_db -c 'SELECT json_build_object('"'"'notificationsAfterTests'"'"',count(*)) FROM public."Notifications";'
